import type { ReactNode } from 'react';

type Size = 'sm' | 'xs' | 'xxs';

export type InfoLabelProps = {
  size?: Size;
  head?: ReactNode;
  body?: ReactNode;
  className?: string;
};

const bodyFontClass: Record<Size, string> = {
  sm: 'fm-font-label-lg',
  xs: 'fm-font-label-md',
  xxs: 'fm-font-label-sm',
};

export function InfoLabel({ size = 'sm', head, body, className = '' }: InfoLabelProps) {
  return (
    <div
      className={className}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--Component-text-to-element-gap-xs)',
        paddingTop: 'var(--Component-vertical-padding-xs)',
        paddingBottom: 'var(--Component-vertical-padding-xs)',
      }}
    >
      <span className="fm-font-text-sm" style={{ color: 'var(--basic-content-soft)' }}>
        {head}
      </span>
      <span className={bodyFontClass[size]} style={{ color: 'var(--basic-content-default)' }}>
        {body}
      </span>
    </div>
  );
}
